const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:10000' },
      { kind: 'text', payload: '图上距离 7 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '7' },
      { kind: 'text', payload: '实际距离 70000 厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = H * 0.55;
    var x0 = W * 0.12;
    var x1 = W * 0.88;
    var baseline = [['M', x0, y], ['L', x1, y]];
    var ticks = [];
    var n = 7;
    for (var i = 0; i <= n; i++) {
      var x = x0 + (x1 - x0) * i / n;
      var half = (i === 0 || i === n) ? 9 : 5;
      ticks.push(['M', x, y - half]);
      ticks.push(['L', x, y + half]);
    }
    return {
      schemaVersion: 1,
      sceneId: 'scale-line',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'baseline', commands: baseline },
        { id: 'ticks', commands: ticks }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'baseline', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: H * 0.20 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: W / 2, y: H * 0.38 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: x0, y: y + 30 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: x1, y: y + 30 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: W / 2, y: H * 0.82 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' }
        ]
      }
    };
  }
};
